<script>
 import {FolderOpen,Download,Check,AlertCircle,Copy} from 'lucide-svelte';import {studio,scope,asset,run,save,refresh,notify,referencePreview,current,liveAssets,importImages} from '../studio.svelte';import {api,stored,persist,rgb,hex,bytes} from '../api';import ScopePicker from './ScopePicker.svelte';
 const initialPreset=stored('export',{format:'webp',width:1000,height:1000,fit:'pad',quality:92,maxBytes:800000,outputDir:'',background:[255,255,255]});let preset=$state(initialPreset);let limit=$state(initialPreset.maxBytes>0),report=$state(null),attempted=$state(0),cancelled=$state(0);
 let leadId=$derived(scope().includes(studio.aid)?studio.aid:scope()[0]);let lead=$derived(current()?.assets.find(a=>a.id===leadId));
 let errors=$derived([!Number.isInteger(preset.width)||preset.width<1||preset.width>16000?'Width must be 1–16000 pixels.':'',!Number.isInteger(preset.height)||preset.height<1||preset.height>16000?'Height must be 1–16000 pixels.':'',preset.width*preset.height>120000000?'Output must be under 120 megapixels.':'',limit&&(!Number.isFinite(preset.maxBytes)||preset.maxBytes<1000)?'Set a limit of at least 1 KB.':'',preset.format!=='png'&&(!Number.isInteger(preset.quality)||preset.quality<1||preset.quality>100)?'Quality must be 1–100.':''].filter(Boolean));
 async function choose(){const path=await api('pick_output');if(path)preset.outputDir=path;}
 async function exportNow(){if(errors.length||!preset.outputDir.trim())return;await run('Exporting',async()=>{const ids=[...scope()];attempted=ids.length;report=null;await save(ids);const settings={...preset,quality:preset.format==='png'?100:preset.quality,maxBytes:limit?preset.maxBytes:0};persist('export',settings);report=await api('export_run',{projectId:studio.pid,ids,preset:settings});cancelled=attempted-report.length;await refresh();const succeeded=report.filter(i=>i.status==='ok').length;notify(`${succeeded} exported${report.length-succeeded?` · ${report.length-succeeded} need attention`:''}${cancelled?` · ${cancelled} cancelled`:''}`);});}
 const status=s=>s==='ok'?'Exported':s==='EXPORT_TARGET_UNREACHABLE'?'Size limit not met':s.split(':')[0].replaceAll('_',' ').toLowerCase();
</script>
{#if !liveAssets().length}<div class="workflow-panel"><div class="empty"><h2>No images to export</h2><button class="primary" onclick={()=>importImages(false)}>Import images</button></div></div>{:else}<div class="workflow-panel export-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>Export</h1></div><ScopePicker/><div class="export-layout"><div class="export-preview"><img src={leadId===studio.aid?referencePreview():studio.thumbs[leadId]} alt="Export preview"/><span>{lead?.name}</span>{#if scope().length>1}<span>{scope().length} images will use these output settings</span>{/if}</div><div class="export-form"><div class="section-row"><h3>Output</h3><button class="text-button" type="button" onclick={()=>{preset={format:'webp',width:1000,height:1000,fit:'pad',quality:92,maxBytes:800000,outputDir:'',background:[255,255,255]};limit=true;report=null;persist('export',preset);}}>Reset settings</button></div><label>Format<select aria-label="Export format" bind:value={preset.format}><option value="webp">WebP</option><option value="jpeg">JPEG</option><option value="png">PNG</option></select></label><div class="field-grid"><label>Width<input type="number" aria-label="Export width" min="1" max="16000" step="1" bind:value={preset.width}/></label><label>Height<input type="number" aria-label="Export height" min="1" max="16000" step="1" bind:value={preset.height}/></label></div><label>Fit<select aria-label="Export fit" bind:value={preset.fit}><option value="pad">Pad — keep the whole image</option><option value="crop">Crop — fill the frame</option></select></label><label>Background<input type="color" value={hex(preset.background)} onchange={e=>preset.background=rgb(e.target.value)}/></label>{#if preset.format!=='png'}<label>Quality<input aria-label="Export quality" type="number" min="1" max="100" bind:value={preset.quality}/></label>{/if}<label class="checkbox-label"><input type="checkbox" bind:checked={limit}/>Limit file size</label>{#if limit}<label>Maximum KB<input aria-label="Maximum KB" type="number" min="1" value={preset.maxBytes/1000} oninput={e=>preset.maxBytes=Number(e.target.value)*1000}/></label>{#if preset.format==='png'}<p class="hint">PNG is lossless. Reduce dimensions or choose WebP if the limit cannot be met.</p>{/if}{/if}<label>Folder<div class="input-action"><input aria-label="Export folder" bind:value={preset.outputDir} placeholder="Choose an output folder"/><button aria-label="Choose export folder" onclick={()=>run('Choosing folder',choose)}><FolderOpen size={17}/></button></div></label>{#each errors as error}<p class="field-error" role="status">{error}</p>{/each}<button class="primary full" disabled={!!studio.busy||!scope().length||!!errors.length||!preset.outputDir.trim()} onclick={exportNow}><Download size={16}/>Export {scope().length} {scope().length===1?'image':'images'}</button>{#if !preset.outputDir.trim()}<p class="hint">Choose an output folder to continue.</p>{/if}</div></div>{#if report}<div class="export-results"><h3>Export report · {report.filter(i=>i.status==='ok').length} / {attempted} exported</h3>{#if cancelled}<p class="hint">{cancelled} images cancelled before processing.</p>{/if}{#each report as item}<div class="result-row">{#if item.path}<Check size={15}/>{:else}<AlertCircle size={15}/>{/if}<span>{item.name}<small>{item.path|| (item.status==='EXPORT_TARGET_UNREACHABLE'?'Increase the size limit, reduce dimensions or try WebP.':item.status)}</small></span><b>{bytes(item.bytes)}</b><em>{status(item.status)}</em>{#if item.path}<button aria-label={`Copy path for ${item.name}`} onclick={async()=>{try{await navigator.clipboard.writeText(item.path);notify('Path copied');}catch{notify('Select the path to copy it');}}}><Copy size={14}/></button>{/if}</div>{/each}</div>{/if}</div>
{/if}

